{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "openrtb-v2_1-schema-bid_request",
    "description": "json schema for an openrtb v2.1 bid request (http://www.iab.net/media/file/OpenRTB-API-Specification-Version-2-1-FINAL.pdf)",
    "type": "object",
    "required": [
        "id",
        "imp"
    ],
    "not": {
        "allOf": [
            {
                "required": [
                    "site"
                ]
            },
            {
                "required": [
                    "app"
                ]
            }
        ]
    },
    "additionalProperties": false,
    "properties": {
        "id": {
            "title": "Id (id)",
            "description": "Unique ID of the bid request, provided by the exchange.",
            "type": "string"
        },
        "imp": {
            "type": "array",
            "title": "Impressions (impressions)",
            "description": "Array of impression objects. Multiple impression auctions may be specified in a single bid request. At least one impression is required for a valid bid request.",
            "items": {
                "$ref": "#/definitions/imp"
            }
        },
        "site": {
            "title": "Publisher Site (site)",
            "description": "Publisher site definition.  A bid request must not contain both a site object and an app object.",
            "$ref": "#/definitions/site"
        },
        "app": {
            "title": "Publishing Application (app)",
            "description": "Publisher application definition.  A bid request must not contain both a site object and an app object.",
            "$ref": "#/definitions/app"
        },
        "device": {
            "title": "Device (device)",
            "description": "User device defnition.",
            "$ref": "#/definitions/device"
        },
        "user": {
            "title": "User (user)",
            "description": "User definition",
            "$ref": "#/definitions/user"
        },
        "at": {
            "title": "Auction type (at)",
            "description": "If \u201c1\u201d, then first price auction. If \u201c2\u201d, then second price auction. Additional auction types can be defined as per the exchange\u2019s business rules.  Exchange specific rules should be numbered over 500",
            "type": "integer"
        },
        "tmax": {
            "title": "Maximum Bid Time (tmax)",
            "description": "Maximum amount of time in milliseconds to submit a bid (e.g., 120 means the bidder has 120ms to submit a bid before the auction is complete). If this value never changes across an exchange, then the exchange can supply this information offline.",
            "$ref": "#/definitions/positive_int"
        },
        "wseat": {
            "title": "Buyer Seats (wseat)",
            "description": "Array of buyer seats allowed to bid on this auction. Seats are an optional feature of exchange. For example, ['4','34','82','A45'] indicates that only advertisers using these exchange seats are allowed to bid on the impressions in this auction",
            "type": "array",
            "items": {
                "type": "string"
            }
        },
        "allimps": {
            "title": "All Impression Availability (allimps)",
            "description": "Flag to indicate whether Exchange can verify that all impressions offered represent all of the impressions available in context (e.g., all impressions available on the web page; all impressions available for a video [pre, mid and postroll spots], etc.) to support road-blocking. A true value should only be passed if the exchange is aware of all impressions in context for the publisher. '0' means the exchange cannot verify, and '1' means that all impressions represent all impressions available.",
            "$ref": "#/definitions/boolean_int"
        },
        "cur": {
            "title": "Currencies (cur)",
            "description": "Array of allowed currencies for bids on this bid request using ISO-4217 alphabetic codes. If only one currency is used by the exchange, this parameter is not required.",
            "type": "array",
            "items": {
                "$ref": "#/definitions/currency"
            }
        },
        "bcat": {
            "title": "Blocked Advertiser Categories (bcat)",
            "description": "Blocked Advertiser Categories. Note that there is no existing categorization / taxonomy of advertiser industries. However, as a substitute exchanges may decide to use IAB categories as an approximation (See Table 6.1 Content Categories)",
            "type": "array",
            "items": {
                "type": "string"
            }
        },
        "badv": {
            "title": "Blocked Advertiser Domains (badv)",
            "description": "Array of strings of blocked toplevel domains of advertisers. For example, {'company1.com', 'company2.com'}",
            "type": "array",
            "items": {
                "type": "string"
            }
        },
        "ext": {
            "title": "Custom JSON (ext)",
            "description": "This object is a placeholder that may contain custom JSON agreed to by the parties in an OpenRTB transaction to support flexibility beyond the standard defined in this specification.",
            "type": "object"
        }
    },
    "definitions": {
        "imp": {
            "type": "object",
            "required": [
                "id"
            ],
            "anyOf": [
                {
                    "required": [
                        "banner"
                    ]
                },
                {
                    "required": [
                        "video"
                    ]
                }
            ],
            "additionalProperties": false,
            "properties": {
                "id": {
                    "title": "Impression Id (id)",
                    "description": "A unique identifier for this impression within the context of the bid request (typically, value starts with 1, and increments up to n for n impressions)",
                    "type": "string"
                },
                "banner": {
                    "title": "A banner object (banner)",
                    "description": "A reference to a banner object. Either a banner or video object(or both if the impression could be either) must be included in an impression object",
                    "$ref": "#/definitions/banner"
                },
                "video": {
                    "title": "A video object (video)",
                    "description": "A reference to a video object. Either a banner or video object (or both if the impression could be either) must be included in an impression object.",
                    "$ref": "#/definitions/video"
                },
                "displaymanager": {
                    "title": "Video/Native display manager (displaymanager)",
                    "description": "Name of ad mediation partner, SDK technology, or native player responsible for rendering ad (typically video or mobile). Used by some ad servers to customize ad code by partner.",
                    "type": "string"
                },
                "displaymanagerver": {
                    "title": "Video/Native display manager version (displaymanagerver)",
                    "description": "Version of ad mediation partner, SDK technology, or native player responsible for rendering ad (typically video or mobile). Used by some ad servers to customize ad code by partner",
                    "type": "string"
                },
                "instl": {
                    "title": "Interstitial/Full Screen (instl)",
                    "description": "1 if the ad is interstitial or full screen; else 0 (i.e., no).",
                    "$ref": "#/definitions/boolean_int"
                },
                "tagid": {
                    "title": "Tag id (tagid)",
                    "description": "Identifier for specific ad placement or ad tag that was used to initiate the auction. This can be useful for debugging of any issues, or for optimization by the buyer.",
                    "type": "string"
                },
                "bidfloor": {
                    "title": "Bid Floor (bidfloor)",
                    "description": "Bid floor for this impression (in CPM of bidfloorcur).",
                    "type": "number",
                    "minimum": 0
                },
                "bidfloorcur": {
                    "title": "Bid Floor Currency (bidfloorcur)",
                    "description": "If bid floor is specified and multiple currencies supported per bid request, then currency should be specified here using ISO-4217 alphabetic codes. Note, this may be different from bid currency returned by bidder, if this is allowed on an exchange.",
                    "$ref": "#/definitions/currency"
                },
                "iframebuster": {
                    "title": "Iframe Buster Names (iframebuster)",
                    "description": "Array of names for supported iframe busters. Exchange specific.",
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                },
                "ext": {
                    "title": "Custom JSON (ext)",
                    "description": "This object is a placeholder that may contain custom JSON agreed to by the parties in an OpenRTB transaction to support flexibility beyond the standard defined in this specification.",
                    "type": "object"
                }
            }
        },
        "banner": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
                "w": {
                    "title": "Width (w)",
                    "description": "Width of the impression in pixels. Since some ad types are not restricted by size this field is not required, but it\u2019s highly recommended that this information be included when possible.",
                    "$ref": "#/definitions/positive_int"
                },
                "h": {
                    "title": "Height (h)",
                    "description": "Height of the impression in pixels. Since some ad types are not restricted by size this field is not required, but it\u2019s highly recommended that this information be included when possible.",
                    "$ref": "#/definitions/positive_int"
                },
                "id": {
                    "title": "Banner Id (id)",
                    "description": "Unique identifier for this banner object. Useful for tracking multiple banner objects (e.g., in companion banner array). Usually starts with 1, increasing with each object. Combination of impression id banner object should be unique.",
                    "type": "string"
                },
                "pos": {
                    "title": "Ad Position (pos)",
                    "description": "Ad Position. Use Table 6.5",
                    "$ref": "#/definitions/ad_position"
                },
                "btype": {
                    "title": "Blocked Creative Types (btype)",
                    "description": "Blocked creative types. See Table 6.2 Banner Ad Types. If blank, assume all types are allowed.",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/banner_ad_type"
                    }
                },
                "battr": {
                    "title": "Blocked Creative Attributes (battr)",
                    "description": "Blocked creative attributes. See Table 6.3 Creative Attributes. If blank assume all types are allowed.",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/creative_attribute"
                    }
                },
                "mimes": {
                    "title": "Mime type whitelist (mimes)",
                    "description": "Whitelist of content MIME types supported. Popular MIME types include, but are not limited to 'image/jpg', 'image/gif' and 'application/x-shockwave-flash'",
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                },
                "topframe": {
                    "title": "Delivery frame (topframe)",
                    "description": "Specify if the banner is delivered in the top frame or in an iframe. '0' means it is not in the top frame, and '1' means that it is.",
                    "$ref": "#/definitions/boolean_int"
                },
                "expdir": {
                    "title": "Expandable properties (expdir)",
                    "description": "Specify properties for an expandable ad. See Table 6.11 Expandable Direction for possible values.",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/expandable_direction"
                    }
                },
                "api": {
                    "title": "Supported API frameworks (api)",
                    "description": "List of supported API frameworks for this banner. (See Table 6.4 API Frameworks). If an API is not explicitly listed it is assumed not to be supported.",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/api_framework"
                    }
                },
                "ext": {
                    "title": "Custom JSON (ext)",
                    "description": "This object is a placeholder that may contain custom JSON agreed to by the parties in an OpenRTB transaction to support flexibility beyond the standard defined in this specification.",
                    "type": "object"
                }
            }
        },
        "video": {
            "type": "object",
            "required": [
                "mimes",
                "linearity",
                "minduration",
                "maxduration",
                "protocol"
            ],
            "additionalProperties": false,
            "properties": {
                "mimes": {
                    "title": "Mime type whitelist (mimes)",
                    "description": "Content MIME types supported. Popular MIME types include, but are not limited to 'video/x-mswmv' for Windows Media, and 'video/x-flv' for Flash Video.",
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                },
                "linearity": {
                    "title": "Video Linearity (linearity)",
                    "description": "Indicates whether the ad impression is linear or non-linear. See Table 6.6 Video Linearity for a list of the possible values",
                    "$ref": "#/definitions/video_linearity"
                },
                "minduration": {
                    "title": "Minimum Duration (minduration)",
                    "description": "Minimum video ad duration in seconds",
                    "$ref": "#/definitions/positive_int"
                },
                "maxduration": {
                    "title": "Maximum Duration (maxduration)",
                    "description": "Maximum video ad duration in seconds",
                    "$ref": "#/definitions/positive_int"
                },
                "protocol": {
                    "title": "Protocol (protocol)",
                    "description": "Video bid response protocols.  See Table 6.7 Video Bid Response Protocols for a list of possible values",
                    "$ref": "#/definitions/video_bid_response_protocol"
                },
                "w": {
                    "title": "Player Width (w)",
                    "description": "Width of the player in pixels. This field is not required, but it\u2019s highly recommended that this information be included.",
                    "$ref": "#/definitions/positive_int"
                },
                "h": {
                    "title": "Player Height (h)",
                    "description": "Height of the player in pixels. This field is not required, but it\u2019s highly recommended that this information be included.",
                    "$ref": "#/definitions/positive_int"
                },
                "startdelay": {
                    "title": "Start Delay (startdelay)",
                    "description": "Indicates the start delay in seconds for preroll, midroll, or postroll ad placement. See Table 6.9 Video Start Delay for generic placement values",
                    "$ref": "#/definitions/video_start_delay"
                },
                "sequence": {
                    "title": "Ad Sequency (sequence)",
                    "description": "If multiple ad impressions are offered in the same bid request, the sequence number will allow for the coordinated delivery of multiple creatives",
                    "type": "integer"
                },
                "battr": {
                    "title": "Blocked creative attributes (battr)",
                    "description": "Blocked creative attributes. See Table 6.3 Creative Attributes. If blank assume all types are allowed.",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/creative_attribute"
                    }
                },
                "maxextended": {
                    "title": "Maximum extended duration (maxextended)",
                    "description": "Maximum extended video ad duration, if extension is allowed.  If blank or 0, extension is not allowed. If -1, extension is allowed, and there is no time limit imposed. If greater than 0, then the value represents the number of seconds of extended play supported beyond the maxduration value. ",
                    "type": "integer",
                    "minimum": -1
                },
                "minbitrate": {
                    "title": "Minimum bitrate (minbitrate)",
                    "description": "Minimum bit rate in Kbps. Exchange may set this dynamically, or universally across their set of publishers.",
                    "$ref": "#/definitions/positive_int"
                },
                "maxbitrate": {
                    "title": "Maximum bitrate (maxbitrate)",
                    "description": "Maximum bit rate in Kbps. Exchange may set this dynamically, or universally across their set of publishers.",
                    "$ref": "#/definitions/positive_int"
                },
                "boxingallowed": {
                    "title": "Boxing (boxingallowed)",
                    "description": "If exchange publisher has rules preventing letter boxing of 4x3 content to play in a 16x9 window, then this should be set to false. Default setting is true, which assumes that boxing of content to fit into a window is allowed. '1' indicates boxing is allowed. '0' indicates it is not allowed.",
                    "$ref": "#/definitions/boolean_int"
                },
                "playbackmethod": {
                    "title": "Playback methods (playbackmethod)",
                    "description": "List of allowed playback methods. If blank, assume that all are allowed. See Table 6.8 Video Playback Methods for a list of possible values.",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/video_playback_method"
                    }
                },
                "delivery": {
                    "title": "Delivery methods (delivery)",
                    "description": "List of supported delivery methods (streaming, progressive). If blank, assume all are supported. See Table 6.12 Content Delivery Methods for a list of possible values.",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/content_delivery_method"
                    }
                },
                "pos": {
                    "title": "Position (pos)",
                    "description": "Ad Position (see table 6.5)",
                    "$ref": "#/definitions/ad_position"
                },
                "companionad": {
                    "title": "Companion Ads (companionad)",
                    "description": "If companion ads are available, they can be listed as an array of banner objects. See Banner Object.",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/banner"
                    }
                },
                "api": {
                    "title": "Supported APIs (api)",
                    "description": "List of supported API frameworks for this impression. (See Table 6.4 API Frameworks). If an API is not explicitly listed it is assumed not to be supported.",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/api_framework"
                    }
                },
                "companiontype": {
                    "title": "Companion Types (companiontype)",
                    "description": "Recommended if companion objects are included. See Table 6.17 VAST Companion Types for a list of possible values.",
                    "type": "array",
                    "$ref": "#/definitions/vast_companion_type"
                },
                "ext": {
                    "title": "Custom JSON (ext)",
                    "description": "This object is a placeholder that may contain custom JSON agreed to by the parties in an OpenRTB transaction to support flexibility beyond the standard defined in this specification.",
                    "type": "object"
                }
            }
        },
        "site": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
                "id": {
                    "title": "Site Id (id)",
                    "description": "Site ID on the exchange",
                    "type": "string"
                },
                "name": {
                    "title": "Site Name (name)",
                    "description": "Site name (may be masked at publisher\u2019s request).",
                    "type": "string"
                },
                "domain": {
                    "title": "Site Domain (domain)",
                    "description": "Domain of the site, used for advertiser side blocking. For example, 'foo.com'.",
                    "type": "string"
                },
                "cat": {
                    "title": "Site Categories (cat)",
                    "description": "Array of IAB content categories for the overall site. See Table 6.1 Content Categories.",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/content_category"
                    }
                },
                "sectioncat": {
                    "title": "Site Section Categories (sectioncat)",
                    "description": "Array of IAB content categories for the current subsection of the site. See Table 6.1 Content Categories.",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/content_category"
                    }
                },
                "pagecat": {
                    "title": "Page Categories (pagecat)",
                    "description": "Array of IAB content categories for the current page. See Table 6.1 Content Categories.",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/content_category"
                    }
                },
                "page": {
                    "title": "Page URL (page)",
                    "description": "URL of the page where the impression will be shown.",
                    "type": "string"
                },
                "privacypolicy": {
                    "title": "Privacy Policy (privacypolicy)",
                    "description": "Specifies whether the site has a privacy policy. '1' means there is a policy. '0' means there is not.",
                    "$ref": "#/definitions/boolean_int"
                },
                "ref": {
                    "title": "Referal URL (ref)",
                    "description": "Referrer URL that caused navigation to the current page.",
                    "type": "string"
                },
                "search": {
                    "title": "Search String (search)",
                    "description": "Search string that caused navigation to the current page.",
                    "type": "string"
                },
                "publisher": {
                    "title": "Publisher (publisher)",
                    "description": "Exchange publisher",
                    "$ref": "#/definitions/publisher"
                },
                "content": {
                    "title": "Content (content)",
                    "description": "Site content",
                    "$ref": "#/definitions/content"
                },
                "keywords": {
                    "title": "Keywords (keywords)",
                    "description": "List of keywords describing this site in a comma separated string.",
                    "type": "string"
                },
                "ext": {
                    "title": "Custom JSON (ext)",
                    "description": "This object is a placeholder that may contain custom JSON agreed to by the parties in an OpenRTB transaction to support flexibility beyond the standard defined in this specification.",
                    "type": "object"
                }
            }
        },
        "app": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
                "id": {
                    "title": "App Id (id)",
                    "description": "Application ID on the exchange.",
                    "type": "string"
                },
                "name": {
                    "title": "App Name (name)",
                    "description": "Application name (may be masked at publisher\u2019s request).",
                    "type": "string"
                },
                "domain": {
                    "title": "App Domain Name (domain)",
                    "description": "Domain of the application (e.g., 'mygame.foo.com').",
                    "type": "string"
                },
                "cat": {
                    "title": "App Categories (cat)",
                    "description": "Array of IAB content categories for the overall application. See Table 6.1 Content Categories.",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/content_category"
                    }
                },
                "sectioncat": {
                    "title": "App Section Categories (sectioncat)",
                    "description": "Array of IAB content categories for the current subsection of the app. See Table 6.1 Content Categories.",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/content_category"
                    }
                },
                "pagecat": {
                    "title": "App Page/View Categories (pagecat)",
                    "description": "Array of IAB content categories for the current page/view of the app. See Table 6.1 Content Categories.",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/content_category"
                    }
                },
                "ver": {
                    "title": "App Version (ver)",
                    "description": "Application version.",
                    "type": "string"
                },
                "bundle": {
                    "title": "App Bundle (bundle)",
                    "description": "Application bundle or package name (e.g., com.foo.mygame). This is intended to be a unique ID across multiple exchanges.",
                    "type": "string"
                },
                "privacypolicy": {
                    "title": "App Privacy Policy (privacypolicy)",
                    "description": "Specifies whether the app has a privacy policy. '1' means there is a policy and '0' means there is not",
                    "$ref": "#/definitions/boolean_int"
                },
                "paid": {
                    "title": "App Type (paid)",
                    "description": "'1' if the application is a paid version; else '0' (i.e., free).",
                    "$ref": "#/definitions/boolean_int"
                },
                "publisher": {
                    "title": "App Publisher (publisher)",
                    "description": "Exchange Application Publisher.",
                    "$ref": "#/definitions/publisher"
                },
                "content": {
                    "title": "App Content (content)",
                    "description": "Exchange Application Content.",
                    "$ref": "#/definitions/content"
                },
                "keywords": {
                    "title": "Keywords (keywords)",
                    "description": "List of keywords describing this app in a comma separated string",
                    "type": "string"
                },
                "storeurl": {
                    "title": "App Store URL (storeurl)",
                    "description": "For QAG 1.5 compliance, an app store URL for an installed app should be passed in the bid request.",
                    "type": "string"
                },
                "ext": {
                    "title": "Custom JSON (ext)",
                    "description": "This object is a placeholder that may contain custom JSON agreed to by the parties in an OpenRTB transaction to support flexibility beyond the standard defined in this specification.",
                    "type": "object"
                }
            }
        },
        "content": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
                "id": {
                    "title": "Content Id (id)",
                    "description": "ID uniquely identifying the content",
                    "type": "string"
                },
                "episode": {
                    "title": "Episode Number (episode)",
                    "description": "Content episode number (typically applies to video content).",
                    "type": "integer"
                },
                "title": {
                    "title": "Title (title)",
                    "description": "Content title. Video examples: 'Search Committee' (television) or 'A New Hope' (movie) or 'Endgame' (made for web) Non-video example: 'Why an Antarctic Glacier Is Melting So Quickly' (Time magazine article)",
                    "type": "string"
                },
                "series": {
                    "title": "Series (series)",
                    "description": "Content series. Video examples: 'The Office' (television) or 'Star Wars' (movie) or 'Arby \u2018N\u2019 The Chief' (made for web) Non-video example: 'Ecocentric' (Time magazine blog)",
                    "type": "string"
                },
                "season": {
                    "title": "Season (season)",
                    "description": "Content season. E.g., 'Season 3' (typically applies to video content).",
                    "type": "string"
                },
                "url": {
                    "title": "URL (url)",
                    "description": "Original URL of the content, for buy-side contextualization or review",
                    "type": "string"
                },
                "cat": {
                    "title": "Categories (cat)",
                    "description": "Array of IAB content categories for the content. See Table 6.1 Content Categories.",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/content_category"
                    }
                },
                "videoquality": {
                    "title": "Video Quality (videoquality)",
                    "description": "Video quality per the IAB\u2019s classification. See Table 6.14 Video Quality.",
                    "$ref": "#/definitions/video_quality"
                },
                "keywords": {
                    "title": "Keywords (keywords)",
                    "description": "Comma separated list of keywords describing the content",
                    "type": "string"
                },
                "contentrating": {
                    "title": "Rating (contentrating)",
                    "description": "Content rating (e.g., MPAA)",
                    "type": "string"
                },
                "userrating": {
                    "title": "User Rating (userrating)",
                    "description": "User rating of the content (e.g., number of stars, likes, etc.).",
                    "type": "string"
                },
                "context": {
                    "title": "Type (context)",
                    "description": "Specifies the type of content (game, video, text, etc.). See Table 6.13 Content Context.",
                    "$ref": "#/definitions/content_context"
                },
                "livestream": {
                    "title": "Live (livestream)",
                    "description": "Is content live? E.g., live video stream, live blog. '1' means content is live. '0' means it is not live.",
                    "$ref": "#/definitions/boolean_int"
                },
                "sourcerelationship": {
                    "title": "Relationship with Source (sourcerelationship)",
                    "description": "1 for 'direct'; 0 for 'indirect'",
                    "$ref": "#/definitions/boolean_int"
                },
                "producer": {
                    "title": "Producer (producer)",
                    "description": "Content Producer.",
                    "$ref": "#/definitions/producer"
                },
                "len": {
                    "title": "Length in seconds (len)",
                    "description": "Length of content (appropriate for video or audio) in seconds.",
                    "$ref": "#/definitions/positive_int"
                },
                "qagmediarating": {
                    "title": "QAG rating (qagmediarating)",
                    "description": "Media rating of the content, per QAG guidelines. See Table 0 QAG Media Ratings for list of possible values",
                    "$ref": "#/definitions/qag_media_rating"
                },
                "embeddable": {
                    "title": "Embedability (embeddable)",
                    "description": "From QAG Video Addendum. If content can be embedded (such as an embeddable video player) this value should be set to '1'. If content cannot be embedded, then this should be set to '0'. ",
                    "$ref": "#/definitions/boolean_int"
                },
                "language": {
                    "title": "Content language (language)",
                    "description": "Language of the content. Use alpha-2/ISO 639-1 codes",
                    "$ref": "#/definitions/language"
                },
                "ext": {
                    "title": "Custom JSON (ext)",
                    "description": "This object is a placeholder that may contain custom JSON agreed to by the parties in an OpenRTB transaction to support flexibility beyond the standard defined in this specification.",
                    "type": "object"
                }
            }
        },
        "publisher": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
                "id": {
                    "title": "Publisher Id (id)",
                    "description": "Publisher ID on the exchange",
                    "type": "string"
                },
                "name": {
                    "title": "Publisher Name (name)",
                    "description": "Publisher name (may be masked at publisher\u2019s request).",
                    "type": "string"
                },
                "cat": {
                    "title": "Publisher Categories (cat)",
                    "description": "Array of IAB content categories for the publisher. See Table 6.1 Content Categories.",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/content_category"
                    }
                },
                "domain": {
                    "title": "Publisher Domain (domain)",
                    "description": "Publisher\u2019s highest level domain name, for example 'foopub.com'.",
                    "type": "string"
                },
